-- Development/demo data only. Run after migrations 001–004 in a non-production Supabase project.
do $$
declare demo_client uuid; seo uuid; meta uuid; social uuid; web uuid; demo_project uuid;
begin
  select id into demo_client from public.clients where slug='acme-fashion-demo';
  if demo_client is null then insert into public.clients(company_name,slug,status,industry,package_name,contact_name,contact_email) values ('Acme Fashion Pvt Ltd','acme-fashion-demo','active','Fashion & Lifestyle','Growth Partner','Demo Client','demo@example.com') returning id into demo_client; end if;
  select id into seo from public.services where slug='seo'; select id into meta from public.services where slug='meta-ads'; select id into social from public.services where slug='social-media'; select id into web from public.services where slug='website-development';
  select id into demo_project from public.projects where client_id=demo_client and title='Commerce experience refresh' order by created_at desc limit 1;
end $$;
